-- JOBSEARCH-OPS-1 (2026-10-27, charter pillar reach): server-side operations for qnfo-jobsearch (failure-mode audit, 8 detectors, self-heal tables, e-mailed-code sign-in).
-- The worker also creates these four tables on first use (CREATE TABLE IF NOT EXISTS), so deploy order does not matter.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DROP TABLE IF EXISTS jobsearch_feeds; DROP TABLE IF EXISTS jobsearch_meta; DROP TABLE IF EXISTS jobsearch_codes; DROP TABLE IF EXISTS jobsearch_sessions; UPDATE remediation_contracts SET status = 'retired' WHERE class LIKE 'fm-jobsearch-%'; UPDATE failure_modes SET detector = detector || ' (retired)' WHERE fm_key LIKE 'jobsearch-%';
CREATE TABLE IF NOT EXISTS jobsearch_feeds (feed TEXT PRIMARY KEY, last_ok_at TEXT, last_count INTEGER, last_error TEXT, last_error_at TEXT, consecutive_fail INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS jobsearch_meta (k TEXT PRIMARY KEY, v TEXT, updated_at TEXT);
CREATE TABLE IF NOT EXISTS jobsearch_codes (id INTEGER PRIMARY KEY AUTOINCREMENT, code_hash TEXT NOT NULL, salt TEXT NOT NULL, created_ms INTEGER NOT NULL, expires_ms INTEGER NOT NULL, tries INTEGER NOT NULL DEFAULT 0, used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS jobsearch_sessions (token_hash TEXT PRIMARY KEY, created_ms INTEGER NOT NULL, expires_ms INTEGER NOT NULL, revoked INTEGER NOT NULL DEFAULT 0);

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius)
VALUES ('jobsearch-cron-stalled', 'the hourly job-match run stops, so the page shows old matches as current', 'the pipeline lives in one cron trigger (15 * * * *); a deploy that drops the trigger, a Workers outage or an exception before the run row closes all look the same from outside: nothing new arrives and nothing says so', 'qnfo-jobsearch records every run in jobsearch_runs and GET /api/ops reports the age of the last finished run; a stalled run is retried by the next tick and by POST /api/run (10-minute cooldown); a missing trigger is restored by redeploying through the canonical path', 'the fm-jobsearch-cron-stalled contract reads: no finished jobsearch_runs row in the last 120 minutes', 'fm-jobsearch-cron-stalled', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), NULL, 'no finished jobsearch_runs row in the last 120 minutes', 'the page shows stale, empty or unusable job matches, or the owner cannot act on them', 'the owner''s job search and the claims drafted in his name (qnfo-jobsearch only)');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
VALUES ('fm-jobsearch-cron-stalled', NULL, 'JOBSEARCH-OPS-1', 'failure-mode detector', 'SELECT ''0'' AS expected, CAST(CASE WHEN (SELECT MAX(finished_at) FROM jobsearch_runs) >= strftime(''%Y-%m-%dT%H:%M:%fZ'',''now'',''-120 minutes'') THEN 0 ELSE 1 END AS TEXT) AS observed', 'd1-query', 3, 'qnfo-jobsearch', 1, 'active', 'failure-mode', datetime('now'));

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius)
VALUES ('jobsearch-run-unfinished', 'a run row stays open forever after an isolate is killed or a D1 write fails', 'the run row is inserted before the work and closed after it, so any crash in between leaves finished_at NULL and nothing distinguishes a long run from a dead one', 'the next run closes every run that has been open for 15 minutes with an explanatory error, and a failed run records its own error and rethrows (logged as run-failed)', 'the fm-jobsearch-run-unfinished contract reads: jobsearch_runs rows with finished_at NULL older than 15 minutes', 'fm-jobsearch-run-unfinished', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), NULL, 'jobsearch_runs rows with finished_at NULL older than 15 minutes', 'the page shows stale, empty or unusable job matches, or the owner cannot act on them', 'the owner''s job search and the claims drafted in his name (qnfo-jobsearch only)');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
VALUES ('fm-jobsearch-run-unfinished', NULL, 'JOBSEARCH-OPS-1', 'failure-mode detector', 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM jobsearch_runs WHERE finished_at IS NULL AND started_at < strftime(''%Y-%m-%dT%H:%M:%fZ'',''now'',''-15 minutes'')) AS TEXT) AS observed', 'd1-query', 3, 'qnfo-jobsearch', 1, 'active', 'failure-mode', datetime('now'));

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius)
VALUES ('jobsearch-feed-down', 'a job feed (Greenhouse, Lever, Ashby, Remotive or Arbeitnow) stays unreachable or changes shape and its postings silently stop arriving', 'each feed is a third-party endpoint with no contract; an outage, a renamed board slug or a schema change returns an error or an empty list, and a single transient failure used to look the same as a permanent one', 'each feed is retried once per run, its streak is kept in jobsearch_feeds, a feed that fails never expires matches, and three failed runs in a row show in /api/ops and fail this detector so the fleet replaces or repairs the board entry (BOARDS in worker.js)', 'the fm-jobsearch-feed-down contract reads: jobsearch_feeds rows with consecutive_fail of 3 or more', 'fm-jobsearch-feed-down', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), NULL, 'jobsearch_feeds rows with consecutive_fail of 3 or more', 'the page shows stale, empty or unusable job matches, or the owner cannot act on them', 'the owner''s job search and the claims drafted in his name (qnfo-jobsearch only)');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
VALUES ('fm-jobsearch-feed-down', NULL, 'JOBSEARCH-OPS-1', 'failure-mode detector', 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM jobsearch_feeds WHERE consecutive_fail >= 3) AS TEXT) AS observed', 'd1-query', 3, 'qnfo-jobsearch', 1, 'active', 'failure-mode', datetime('now'));

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius)
VALUES ('jobsearch-verifier-blocked', 'a draft resume or note fails the claim verifier and the owner sees a blocked match', 'every output sentence must equal a ledger sentence; a ledger edit, a template change or a forbidden-term collision (a posting that names a technology the owner has not claimed) makes the checker reject a draft', 'the match is stored with verified = 0 and the exact reason, it can only be rejected (never approved), and the fix is in the ledger or the template through a PR, never a loosened check', 'the fm-jobsearch-verifier-blocked contract reads: pending jobsearch_matches with verified = 0', 'fm-jobsearch-verifier-blocked', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), NULL, 'pending jobsearch_matches with verified = 0', 'the page shows stale, empty or unusable job matches, or the owner cannot act on them', 'the owner''s job search and the claims drafted in his name (qnfo-jobsearch only)');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
VALUES ('fm-jobsearch-verifier-blocked', NULL, 'JOBSEARCH-OPS-1', 'failure-mode detector', 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM jobsearch_matches WHERE verified = 0 AND status = ''pending_owner_approval'') AS TEXT) AS observed', 'd1-query', 3, 'qnfo-jobsearch', 1, 'active', 'failure-mode', datetime('now'));

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius)
VALUES ('jobsearch-stale-pending', 'matches whose postings were filled or removed stay pending and the owner applies to a closed job', 'postings disappear from a feed without notice and nothing marked them; the page only ever added rows', 'a pending match that its feed did not list for 48 hours (and only when that feed answered this run) becomes expired and leaves the default view; expired and rejected rows are deleted after 90 days', 'the fm-jobsearch-stale-pending contract reads: pending jobsearch_matches not seen for 72 hours (the lifecycle step is not running)', 'fm-jobsearch-stale-pending', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), NULL, 'pending jobsearch_matches not seen for 72 hours (the lifecycle step is not running)', 'the page shows stale, empty or unusable job matches, or the owner cannot act on them', 'the owner''s job search and the claims drafted in his name (qnfo-jobsearch only)');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
VALUES ('fm-jobsearch-stale-pending', NULL, 'JOBSEARCH-OPS-1', 'failure-mode detector', 'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM jobsearch_matches WHERE status = ''pending_owner_approval'' AND last_seen < strftime(''%Y-%m-%dT%H:%M:%fZ'',''now'',''-72 hours'')) AS TEXT) AS observed', 'd1-query', 3, 'qnfo-jobsearch', 1, 'active', 'failure-mode', datetime('now'));

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius)
VALUES ('jobsearch-ledger-stale', 'the claim ledger drifts from the owner''s real record and drafts state outdated facts', 'facts.json is copied by hand from the verified CV and embedded in worker.js; neither updates itself when the CV changes, and the checker only proves drafts equal the ledger, not that the ledger is current', 'the ledger carries ledger_verified_on, the worker records it each run and reports its age; at 90 days this detector fails and the fleet files the review (owner re-verifies the CV, then a PR raises the date); a node test asserts the embedded ledger equals jobsearch/facts.json', 'the fm-jobsearch-ledger-stale contract reads: the ledger date is more than 90 days old', 'fm-jobsearch-ledger-stale', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), NULL, 'the ledger date is more than 90 days old', 'the page shows stale, empty or unusable job matches, or the owner cannot act on them', 'the owner''s job search and the claims drafted in his name (qnfo-jobsearch only)');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
VALUES ('fm-jobsearch-ledger-stale', NULL, 'JOBSEARCH-OPS-1', 'failure-mode detector', 'SELECT ''ok'' AS expected, CASE WHEN (SELECT v FROM jobsearch_meta WHERE k = ''ledger_verified_on'') IS NULL THEN ''pending: no run has recorded the ledger date yet'' WHEN julianday(''now'') - julianday((SELECT v FROM jobsearch_meta WHERE k = ''ledger_verified_on'')) <= 90 THEN ''ok'' ELSE ''fail: ledger verified '' || (SELECT v FROM jobsearch_meta WHERE k = ''ledger_verified_on'') || '' is over 90 days old'' END AS observed', 'd1-query', 3, 'qnfo-jobsearch', 1, 'active', 'failure-mode', datetime('now'));

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius)
VALUES ('jobsearch-intake-collapse', 'the matcher keeps running but fetches or passes almost nothing, so the owner sees an empty page that looks healthy', 'keyword gates and third-party schemas fail soft: a changed field name makes every posting fail a gate without any error', 'the last three runs are compared: fetched under 1000 or passed 0 in each of them fails this detector, and /api/ops shows the figures per run so the broken gate or feed is found from the excluded counts in jobsearch_runs', 'the fm-jobsearch-intake-collapse contract reads: each of the last 3 finished runs fetched under 1000 postings or passed none', 'fm-jobsearch-intake-collapse', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), NULL, 'each of the last 3 finished runs fetched under 1000 postings or passed none', 'the page shows stale, empty or unusable job matches, or the owner cannot act on them', 'the owner''s job search and the claims drafted in his name (qnfo-jobsearch only)');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
VALUES ('fm-jobsearch-intake-collapse', NULL, 'JOBSEARCH-OPS-1', 'failure-mode detector', 'SELECT ''0'' AS expected, CAST(CASE WHEN (SELECT COUNT(*) FROM (SELECT id FROM jobsearch_runs WHERE finished_at IS NOT NULL ORDER BY id DESC LIMIT 3)) = 3 AND (SELECT MAX(CASE WHEN fetched >= 1000 AND passed > 0 THEN 1 ELSE 0 END) FROM (SELECT fetched, passed FROM jobsearch_runs WHERE finished_at IS NOT NULL ORDER BY id DESC LIMIT 3)) = 0 THEN 1 ELSE 0 END AS TEXT) AS observed', 'd1-query', 3, 'qnfo-jobsearch', 1, 'active', 'failure-mode', datetime('now'));

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius)
VALUES ('jobsearch-auth-unavailable', 'the owner cannot sign in and every Approve, Reject and Mark applied is refused', 'the first design needed a LOOP_TOKEN secret that only the owner''s terminal could set; any single credential on the critical path is one point of failure (ANTIFRAGILE-1)', 'sign-in uses the fleet''s e-mailed one-time code through the EMAIL service binding to qnfo-email (props caller qnfo-jobsearch), 3 codes an hour, 5 tries per code, sessions of 12 hours stored hashed; x-loop-token remains a second path when the secret is set', 'the fm-jobsearch-auth-unavailable contract reads: the worker was deployed without the EMAIL binding', 'fm-jobsearch-auth-unavailable', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'), NULL, 'the worker was deployed without the EMAIL binding', 'the page shows stale, empty or unusable job matches, or the owner cannot act on them', 'the owner''s job search and the claims drafted in his name (qnfo-jobsearch only)');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
VALUES ('fm-jobsearch-auth-unavailable', NULL, 'JOBSEARCH-OPS-1', 'failure-mode detector', 'SELECT ''0'' AS expected, CAST(CASE WHEN (SELECT v FROM jobsearch_meta WHERE k = ''email_binding'') = ''1'' THEN 0 ELSE 1 END AS TEXT) AS observed', 'd1-query', 3, 'qnfo-jobsearch', 1, 'active', 'failure-mode', datetime('now'));

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'DOMAIN-PLANE-1:jobs.q08.org: attach the job matches page to a q08.org address', 'Charter pillar: reach. DOMAIN-PLANE-1: the job matches page (the owner''s own career, personal plane) is reachable only at https://qnfo-jobsearch.q08.workers.dev, a machine origin that must not be the address given to the owner. Doer: the loop or session that owns attach routes, using the repository CLOUDFLARE_API_TOKEN (zone route or custom domain plus proxied record, the pattern in scripts/attach-me-q08-route.py and scripts/attach-surface-routes.py); keep the workers.dev origin as a machine host. Definition of done: https://jobs.q08.org/health answers 200 with worker qnfo-jobsearch, and docs/DOMAINS.md lists the host.
runtime-probe: {"url": "https://jobs.q08.org/health", "status": 200, "contains": "qnfo-jobsearch"}', 'session', 'reliability', 'medium', 'open',
  CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'DOMAIN-PLANE-1:jobs.q08.org:%' AND status = 'open');
